<?php
/**
 * Regenerate lh_chat_config.autologin_data.secret_hash on the host this
 * runs on.
 *
 * The sanitized seed ships the hash empty (md_seed_export_main blanks it),
 * and LHC's REST generateautologin route answers 400 "Secret hash value is
 * empty" until a 64-hex value exists — production lived with that break
 * from bring-up until 2026-10-29, when the hash was generated by hand.
 * This script closes that gap from chat-push: it runs on the target host
 * through `wp eval-file`, never touches a hash that is already set, and
 * leaves the rest of the serialized autologin_data structure untouched.
 *
 * The lh_* tables share the WordPress database unprefixed (the seed's
 * REPLACE INTO names `lh_chat_config` literally), so $wpdb reaches the row.
 */

/**
 * Decide what to do with one autologin_data row value.
 *
 * @return array{0: string, 1: string|null} ('present', null) when the hash
 *   is already set; ('empty', <the row re-serialized with a fresh 64-hex
 *   hash>) when it must be regenerated; ('broken', null) when the value
 *   does not unserialize or carries no secret_hash key — the caller must
 *   not guess at a structure it cannot read.
 */
function md_regen_autologin_plan(string $serialized): array
{
    $decoded = @unserialize($serialized);
    if (!is_array($decoded) || !array_key_exists('secret_hash', $decoded)) {
        return ['broken', null];
    }
    if (is_string($decoded['secret_hash']) && $decoded['secret_hash'] !== '') {
        return ['present', null];
    }
    $decoded['secret_hash'] = bin2hex(random_bytes(32));
    return ['empty', serialize($decoded)];
}

if (PHP_SAPI === 'cli' && defined('WP_CLI') && WP_CLI) {
    global $wpdb;
    $row = $wpdb->get_row(
        "SELECT value FROM lh_chat_config WHERE identifier = 'autologin_data'",
        ARRAY_A
    );
    if (!is_array($row)) {
        WP_CLI::error('lh_chat_config autologin_data row is missing');
    }
    [$state, $value] = md_regen_autologin_plan((string) $row['value']);
    if ($state === 'broken') {
        WP_CLI::error('autologin_data does not unserialize; refusing to guess');
    }
    if ($state === 'present') {
        WP_CLI::line('OK autologin_data secret_hash present');
        return;
    }
    $updated = $wpdb->update(
        'lh_chat_config',
        ['value' => $value],
        ['identifier' => 'autologin_data']
    );
    if ($updated === false) {
        WP_CLI::error('the autologin_data update failed: ' . $wpdb->last_error);
    }
    $read = $wpdb->get_var(
        "SELECT value FROM lh_chat_config WHERE identifier = 'autologin_data'"
    );
    $after = md_regen_autologin_plan((string) $read)[0];
    if ($after !== 'present') {
        WP_CLI::error('the regenerated secret_hash did not read back');
    }
    WP_CLI::line('OK autologin_data secret_hash regenerated');
}
